const val=s=>s===''||s===null||s===undefined?NaN:Number(String(s).replace(',','.'));
const fmtKg=n=>format(n,2)+' kg';
const setsVol=sets=>(sets||[]).reduce((a,s)=>a+(Math.max(0,val(s.reps)||0)*Math.max(0,val(s.weight)||0)),0);
const sessionVol=s=>(s.entries||[]).reduce((a,e)=>a+setsVol(e.sets),0);
